  1→/**
  2→ * SdkBridge: tenant-aware agent bridge using in-process AgentSession.
  3→ *
  4→ * Creates AgentSession objects directly via the SDK, calling SDK methods
  5→ * for each WebSocket command and forwarding session events back to the
  6→ * client. Benefits:
  7→ * - No child process overhead
  8→ * - Direct access to session state (model, thinking level, etc.)
  9→ * - Shared event loop — better for multi-tenant server
 10→ * - Closure-based extensions (no env var passing for credentials)
 11→ */
 12→
 13→import { randomUUID } from "node:crypto";
 14→import * as fs from "node:fs/promises";
 15→import * as path from "node:path";
 16→import type { WebSocket } from "ws";
 17→import type { ThinkingLevel } from "@mariozechner/pi-agent-core";
 18→import {
 19→	createAgentSession,
 20→	AuthStorage,
 21→	DefaultResourceLoader,
 22→	ModelRegistry,
 23→	SessionManager,
 24→	SettingsManager,
 25→	type AgentSession,
 26→	type AgentSessionEvent,
 27→	type ExtensionFactory,
 28→	type ExtensionUIContext,
 29→	type ExtensionCommandContextActions,
 30→} from "@mariozechner/pi-coding-agent";
 31→import type { AuthUser } from "./auth/types.js";
 32→
 33→export interface BridgeOptions {
 34→	/** Working directory for the agent */
 35→	cwd?: string;
 36→	/** Provider to use */
 37→	provider?: string;
 38→	/** Model ID to use */
 39→	model?: string;
 40→	/** Additional CLI arguments */
 41→	args?: string[];
 42→	/** System prompt text — replaces the default pi coding-assistant prompt */
 43→	systemPrompt?: string;
 44→	/** System prompt text — appended to the default prompt instead of replacing */
 45→	appendSystemPrompt?: string;
 46→}
 47→import type { CryptoService } from "./services/crypto.js";
 48→import type { SessionPool } from "./services/session-pool.js";
 49→import type { StorageService } from "./services/storage.js";
 50→import type { SessionStatusService } from "./services/session-status-service.js";
 51→import type { OutputBufferService } from "./services/output-buffer.js";
 52→import type { Database } from "./db/types.js";
 53→import { AgentExecutor } from "./services/agent-executor.js";
 54→import { resolveSkillsForUser, type ResolvedSkills } from "./services/skill-resolver.js";
 55→import { resolveFilesForUser, type ResolvedFiles } from "./services/file-resolver.js";
 56→import { resolveMemoryContent } from "./services/memory-resolver.js";
 57→import { issueMemoryToken, revokeMemoryToken } from "./auth/memory-tokens.js";
 58→import { envVarToProvider } from "./utils/reverse-provider-map.js";
 59→import { createAgentMemoryExtension } from "./extensions/agent-memory-factory.js";
 60→import braveSearchExtension from "./extensions/brave-search.js";
 61→import pushToViewerExtension from "./extensions/push-to-viewer.js";
 62→
 63→export interface SdkBridgeOptions extends BridgeOptions {
 64→	user: AuthUser;
 65→	sessionId?: string;
 66→	sessionPool: SessionPool;
 67→	crypto: CryptoService;
 68→	db: Database;
 69→	storage: StorageService;
 70→	sessionStatusService: SessionStatusService;
 71→	outputBufferService: OutputBufferService;
 72→	/** Curated skill IDs from agent profile (undefined = all visible skills) */
 73→	profileSkillIds?: string[];
 74→	/** File IDs from agent profile to inject via --file args */
 75→	profileFileIds?: string[];
 76→	/** Agent profile ID for session metadata tracking */
 77→	agentProfileId?: string;
 78→	/** Port for internal API calls (memory extension) */
 79→	serverPort: number;
 80→}
 81→
 82→export class SdkBridge {
 83→	private ws: WebSocket;
 84→	private options: SdkBridgeOptions;
 85→	private user: AuthUser;
 86→	private sessionId: string;
 87→	private sessionPool: SessionPool;
 88→	private crypto: CryptoService;
 89→	private db: Database;
 90→	private storage: StorageService;
 91→	private sessionStatusService: SessionStatusService;
 92→	private outputBufferService: OutputBufferService;
 93→
 94→	// Session state
 95→	private session: AgentSession | null = null;
 96→	private authStorage: AuthStorage | null = null;
 97→	private resourceLoader: DefaultResourceLoader | null = null;
 98→	private resolvedSkills: ResolvedSkills | null = null;
 99→	private resolvedFiles: ResolvedFiles | null = null;
100→	private memoryToken: string | null = null;
101→	private sessionModel: { id: string; provider: string | null } | null = null;
102→	private conversationHistory: Array<{ role: string; content: any }> | null = null;
103→
104→	// Bridge state
105→	private closed = false;
106→	private detached = false;
107→	private ready = false;
108→	private sessionCreating = false;
109→	private pendingMessages: Array<{ raw: string; parsed: any }> = [];
110→	// Providers explicitly configured via team API keys or user OAuth (via setRuntimeApiKey).
111→	// Used to prefer these over auto-detected providers (e.g., AWS IAM → Bedrock) when
112→	// resolving the default model in sendSyntheticGetState().
113→	private configuredProviders = new Set<string>();
114→	private unsubscribeSession: (() => void) | null = null;
115→
116→	// Extension UI pending promises (for forwarding UI requests to WS client)
117→	private pendingUIRequests = new Map<string, {
118→		resolve: (value: any) => void;
119→		reject: (reason: any) => void;
120→	}>();
121→
122→	constructor(ws: WebSocket, options: SdkBridgeOptions) {
123→		this.ws = ws;
124→		this.options = options;
125→		this.user = options.user;
126→		this.sessionId = options.sessionId || randomUUID();
127→		this.sessionPool = options.sessionPool;
128→		this.crypto = options.crypto;
129→		this.db = options.db;
130→		this.storage = options.storage;
131→		this.sessionStatusService = options.sessionStatusService;
132→		this.outputBufferService = options.outputBufferService;
133→	}
134→
135→	/**
136→	 * Start the bridge: register WebSocket handlers immediately, then
137→	 * async-initialize keys + skills + session.
138→	 */
139→	start(): void {
140→		this.wireUpWebSocket();
141→
142→		this.startAsync().catch((err) => {
143→			console.error("[sdk-bridge] Failed to start:", err);
144→			this.ws.close(1011, "Failed to initialize agent");
145→		});
146→	}
147→
148→	private async startAsync(): Promise<void> {
149→		// Check generating limit before proceeding
150→		const generatingCount = await this.sessionStatusService.getGeneratingCount(this.user.userId, this.db);
151→		if (generatingCount >= 3) {
152→			this.ws.close(4031, "Max 3 concurrent generating sessions");
153→			return;
154→		}
155→
156→		// Run all async prep work in parallel
157→		const [envKeys, , , , memoryContent] = await Promise.all([
158→			// 1. Fetch and inject provider keys + OAuth credentials
159→			new AgentExecutor({ db: this.db, crypto: this.crypto, storage: this.storage })
160→				.buildEnv(this.user.userId, this.user.teamId),
161→
162→			// 2. Resolve skills for this user (filtered by profile if set)
163→			resolveSkillsForUser(
164→				this.db, this.storage, this.user.userId, this.user.teamId,
165→				this.options.profileSkillIds,
166→			).then(skills => {
167→				this.resolvedSkills = skills;
168→				if (skills.skillPaths.length > 0) {
169→					console.log(`[sdk-bridge] Resolved ${skills.skillPaths.length} skill(s)`);
170→				}
171→			}).catch(err => {
172→				console.error("[sdk-bridge] Failed to resolve skills:", err);
173→			}),
174→
175→			// 3. Resolve files from agent profile
176→			(this.options.profileFileIds && this.options.profileFileIds.length > 0
177→				? resolveFilesForUser(
178→					this.db, this.storage, this.user.userId,
179→					this.options.profileFileIds,
180→				).then(files => {
181→					this.resolvedFiles = files;
182→					if (files.filePaths.length > 0) {
183→						console.log(`[sdk-bridge] Resolved ${files.filePaths.length} file(s)`);
184→					}
185→				}).catch(err => {
186→					console.error("[sdk-bridge] Failed to resolve files:", err);
187→				})
188→				: Promise.resolve()
189→			),
190→
191→			// 4. Fetch conversation history + session model for existing sessions
192→			(this.options.sessionId
193→				? Promise.all([
194→					this.db.query<{ role: string; content: any }>(
195→						`SELECT m.role, m.content FROM messages m
196→						 JOIN sessions s ON s.id = m.session_id
197→						 WHERE m.session_id = $1 AND s.user_id = $2
198→						 ORDER BY m.ordinal ASC LIMIT 200`,
199→						[this.options.sessionId, this.user.userId],
200→					).then(result => {
201→						if (result.rows.length > 0) {
202→							this.conversationHistory = result.rows;
203→							console.log(`[sdk-bridge] Fetched ${result.rows.length} history message(s)`);
204→						}
205→					}),
206→					this.db.query<{ model_id: string | null; provider: string | null }>(
207→						`SELECT model_id, provider FROM sessions
208→						 WHERE id = $1 AND user_id = $2 AND deleted_at IS NULL`,
209→						[this.options.sessionId, this.user.userId],
210→					).then(result => {
211→						if (result.rows.length > 0 && result.rows[0].model_id) {
212→							this.sessionModel = {
213→								id: result.rows[0].model_id,
214→								provider: result.rows[0].provider,
215→							};
216→						}
217→					}),
218→				]).catch(err => {
219→					console.error("[sdk-bridge] Failed to fetch conversation history:", err);
220→				})
221→				: Promise.resolve()
222→			),
223→
224→			// 5. Resolve user memories (content string, no temp file)
225→			resolveMemoryContent(this.db, this.user.userId)
226→				.catch(err => {
227→					console.error("[sdk-bridge] Failed to resolve memories:", err);
228→					return { content: null };
229→				}),
230→		]);
231→
232→		// Issue memory token for the extension
233→		this.memoryToken = issueMemoryToken(this.user.userId, this.user.teamId);
234→
235→		// Audit log provider key decryptions (non-blocking)
236→		const providers = Object.keys(envKeys);
237→		if (providers.length > 0) {
238→			const values = providers.map((_, i) => `($1, $2, $${i + 3}, 'decrypt')`).join(", ");
239→			this.db.query(
240→				`INSERT INTO provider_key_audit_log (team_id, user_id, provider, action) VALUES ${values}`,
241→				[this.user.teamId, this.user.userId, ...providers],
242→			).catch(() => {});
243→		}
244→
245→		// Build AuthStorage with runtime API keys from env map
246→		this.authStorage = AuthStorage.inMemory();
247→		for (const [envVar, value] of Object.entries(envKeys)) {
248→			const provider = envVarToProvider(envVar);
249→			if (provider) {
250→				this.authStorage.setRuntimeApiKey(provider, value);
251→				this.configuredProviders.add(provider);
252→			}
253→		}
254→
255→		// Build the system prompt
256→		let systemPrompt: string | undefined;
257→		let appendSystemPrompt: string | undefined;
258→		if (this.options.systemPrompt) {
259→			systemPrompt = this.options.systemPrompt;
260→		} else if (this.options.appendSystemPrompt) {
261→			appendSystemPrompt = this.options.appendSystemPrompt;
262→		}
263→
264→		// Inject conversation history into append system prompt for continuity
265→		if (this.conversationHistory && this.conversationHistory.length > 0) {
266→			const historyBlock = this.formatConversationHistory(this.conversationHistory);
267→			if (systemPrompt) {
268→				systemPrompt = systemPrompt + "\n\n" + historyBlock;
269→			} else if (appendSystemPrompt) {
270→				appendSystemPrompt = appendSystemPrompt + "\n\n" + historyBlock;
271→			} else {
272→				appendSystemPrompt = historyBlock;
273→			}
274→			console.log(`[sdk-bridge] Injected ${this.conversationHistory.length} history messages into system prompt`);
275→		}
276→
277→		// Build extension factories
278→		const extensionFactories: ExtensionFactory[] = [];
279→
280→		// Brave Search extension
281→		if (process.env.BRAVE_SEARCH_API_KEY) {
282→			extensionFactories.push(braveSearchExtension);
283→		}
284→
285→		// Push-to-viewer extension (always available)
286→		extensionFactories.push(pushToViewerExtension);
287→
288→		// Agent memory extension (closure-based, captures token and port)
289→		if (this.memoryToken) {
290→			extensionFactories.push(
291→				createAgentMemoryExtension(this.memoryToken, this.options.serverPort),
292→			);
293→		}
294→
295→		// Build agents files override for memory injection (virtual file, no temp file)
296→		const memContent = memoryContent?.content ?? null;
297→		const agentsFilesOverride = memContent
298→			? (base: { agentsFiles: Array<{ path: string; content: string }> }) => ({
299→				agentsFiles: [
300→					...base.agentsFiles,

