  4→/**
  5→ * Discover models from an Ollama server.
  6→ * @param baseUrl - Base URL of the Ollama server (e.g., "http://localhost:11434")
  7→ * @param apiKey - Optional API key (currently unused by Ollama)
  8→ * @returns Array of discovered models
  9→ */
 10→export async function discoverOllamaModels(baseUrl: string, _apiKey?: string): Promise<Model<any>[]> {
 11→	try {
 12→		// Create Ollama client
 13→		const { Ollama } = await getOllama();
 14→		const ollama = new Ollama({ host: baseUrl });
 15→
 16→		// Get list of available models
 17→		const { models } = await ollama.list();
 18→
 19→		// Fetch details for each model and convert to Model format
 20→		const ollamaModelPromises: Promise<Model<any> | null>[] = models.map(async (model: any) => {
 21→			try {
 22→				// Get model details
 23→				const details = await ollama.show({
 24→					model: model.name,
 25→				});
 26→
 27→				// Check capabilities - filter out models that don't support tools
 28→				const capabilities: string[] = (details as any).capabilities || [];
 29→				if (!capabilities.includes("tools")) {
 30→					console.debug(`Skipping model ${model.name}: does not support tools`);
 31→					return null;
 32→				}
 33→
 34→				// Extract model info
 35→				const modelInfo: any = details.model_info || {};
 36→
 37→				// Get context window size - look for architecture-specific keys
 38→				const architecture = modelInfo["general.architecture"] || "";
 39→				const contextKey = `${architecture}.context_length`;
 40→				const contextWindow = parseInt(modelInfo[contextKey] || "8192", 10);
 41→
 42→				// Ollama caps max tokens at 10x context length
 43→				const maxTokens = contextWindow * 10;
 44→
 45→				// Ollama only supports completions API
 46→				const ollamaModel: Model<any> = {
 47→					id: model.name,
 48→					name: model.name,
 49→					api: "openai-completions" as any,
 50→					provider: "", // Will be set by caller
 51→					baseUrl: `${baseUrl}/v1`,
 52→					reasoning: capabilities.includes("thinking"),
 53→					input: ["text"],
 54→					cost: {
 55→						input: 0,
 56→						output: 0,
 57→						cacheRead: 0,
 58→						cacheWrite: 0,
 59→					},
 60→					contextWindow: contextWindow,
 61→					maxTokens: maxTokens,
 62→				};
 63→
 64→				return ollamaModel;
 65→			} catch (err) {
 66→				console.error(`Failed to fetch details for model ${model.name}:`, err);
 67→				return null;
 68→			}
 69→		});
 70→
 71→		const results = await Promise.all(ollamaModelPromises);
 72→		return results.filter((m): m is Model<any> => m !== null);
 73→	} catch (err) {
 74→		console.error("Failed to discover Ollama models:", err);
 75→		throw new Error(`Ollama discovery failed: ${err instanceof Error ? err.message : String(err)}`);
 76→	}
 77→}
