 79→/**
 80→ * Discover models from a llama.cpp server via OpenAI-compatible /v1/models endpoint.
 81→ * @param baseUrl - Base URL of the llama.cpp server (e.g., "http://localhost:8080")
 82→ * @param apiKey - Optional API key
 83→ * @returns Array of discovered models
 84→ */
 85→export async function discoverLlamaCppModels(baseUrl: string, apiKey?: string): Promise<Model<any>[]> {
 86→	try {
 87→		const headers: HeadersInit = {
 88→			"Content-Type": "application/json",
 89→		};
 90→
 91→		if (apiKey) {
 92→			headers.Authorization = `Bearer ${apiKey}`;
 93→		}
 94→
 95→		const response = await fetch(`${baseUrl}/v1/models`, {
 96→			method: "GET",
 97→			headers,
 98→		});
 99→
100→		if (!response.ok) {
101→			throw new Error(`HTTP ${response.status}: ${response.statusText}`);
102→		}
103→
104→		const data = await response.json();
105→
106→		if (!data.data || !Array.isArray(data.data)) {
107→			throw new Error("Invalid response format from llama.cpp server");
108→		}
109→
110→		return data.data.map((model: any) => {
111→			// llama.cpp doesn't always provide context window info
112→			const contextWindow = model.context_length || 8192;
113→			const maxTokens = model.max_tokens || 4096;
114→
115→			const llamaModel: Model<any> = {
116→				id: model.id,
117→				name: model.id,
118→				api: "openai-completions" as any,
119→				provider: "", // Will be set by caller
120→				baseUrl: `${baseUrl}/v1`,
121→				reasoning: false,
122→				input: ["text"],
123→				cost: {
124→					input: 0,
125→					output: 0,
126→					cacheRead: 0,
127→					cacheWrite: 0,
128→				},
129→				contextWindow: contextWindow,
130→				maxTokens: maxTokens,
131→			};
132→
133→			return llamaModel;
134→		});
135→	} catch (err) {
136→		console.error("Failed to discover llama.cpp models:", err);
137→		throw new Error(`llama.cpp discovery failed: ${err instanceof Error ? err.message : String(err)}`);
138→	}
139→}
