141→/**
142→ * Discover models from a vLLM server via OpenAI-compatible /v1/models endpoint.
143→ * @param baseUrl - Base URL of the vLLM server (e.g., "http://localhost:8000")
144→ * @param apiKey - Optional API key
145→ * @returns Array of discovered models
146→ */
147→export async function discoverVLLMModels(baseUrl: string, apiKey?: string): Promise<Model<any>[]> {
148→	try {
149→		const headers: HeadersInit = {
150→			"Content-Type": "application/json",
151→		};
152→
153→		if (apiKey) {
154→			headers.Authorization = `Bearer ${apiKey}`;
155→		}
156→
157→		const response = await fetch(`${baseUrl}/v1/models`, {
158→			method: "GET",
159→			headers,
160→		});
161→
162→		if (!response.ok) {
163→			throw new Error(`HTTP ${response.status}: ${response.statusText}`);
164→		}
165→
166→		const data = await response.json();
167→
168→		if (!data.data || !Array.isArray(data.data)) {
169→			throw new Error("Invalid response format from vLLM server");
170→		}
171→
172→		return data.data.map((model: any) => {
173→			// vLLM provides max_model_len which is the context window
174→			const contextWindow = model.max_model_len || 8192;
175→			const maxTokens = Math.min(contextWindow, 4096); // Cap max tokens
176→
177→			const vllmModel: Model<any> = {
178→				id: model.id,
179→				name: model.id,
180→				api: "openai-completions" as any,
181→				provider: "", // Will be set by caller
182→				baseUrl: `${baseUrl}/v1`,
183→				reasoning: false,
184→				input: ["text"],
185→				cost: {
186→					input: 0,
187→					output: 0,
188→					cacheRead: 0,
189→					cacheWrite: 0,
190→				},
191→				contextWindow: contextWindow,
192→				maxTokens: maxTokens,
193→			};
194→
195→			return vllmModel;
196→		});
197→	} catch (err) {
198→		console.error("Failed to discover vLLM models:", err);
199→		throw new Error(`vLLM discovery failed: ${err instanceof Error ? err.message : String(err)}`);
200→	}
201→}
