203→/**
204→ * Discover models from an LM Studio server using the LM Studio SDK.
205→ * @param baseUrl - Base URL of the LM Studio server (e.g., "http://localhost:1234")
206→ * @param apiKey - Optional API key (unused for LM Studio SDK)
207→ * @returns Array of discovered models
208→ */
209→export async function discoverLMStudioModels(baseUrl: string, _apiKey?: string): Promise<Model<any>[]> {
210→	try {
211→		// Extract host and port from baseUrl
212→		const url = new URL(baseUrl);
213→		const port = url.port ? parseInt(url.port, 10) : 1234;
214→
215→		// Create LM Studio client
216→		const { LMStudioClient } = await getLMStudio();
217→		const client = new LMStudioClient({ baseUrl: `ws://${url.hostname}:${port}` });
218→
219→		// List all downloaded models
220→		const models = await client.system.listDownloadedModels();
221→
222→		// Filter to only LLM models and map to our Model format
223→		return models
224→			.filter((model) => model.type === "llm")
225→			.map((model) => {
226→				const contextWindow = model.maxContextLength;
227→				// Use 10x context length like Ollama does
228→				const maxTokens = contextWindow;
229→
230→				const lmStudioModel: Model<any> = {
231→					id: model.path,
232→					name: model.displayName || model.path,
233→					api: "openai-completions" as any,
234→					provider: "", // Will be set by caller
235→					baseUrl: `${baseUrl}/v1`,
236→					reasoning: model.trainedForToolUse || false,
237→					input: model.vision ? ["text", "image"] : ["text"],
238→					cost: {
239→						input: 0,
240→						output: 0,
241→						cacheRead: 0,
242→						cacheWrite: 0,
243→					},
244→					contextWindow: contextWindow,
245→					maxTokens: maxTokens,
246→				};
247→
248→				return lmStudioModel;
249→			});
250→	} catch (err) {
251→		console.error("Failed to discover LM Studio models:", err);
252→		throw new Error(`LM Studio discovery failed: ${err instanceof Error ? err.message : String(err)}`);
253→	}
254→}
