262→ */
263→export async function discoverModels(
264→	type: "ollama" | "llama.cpp" | "vllm" | "lmstudio",
265→	baseUrl: string,
266→	apiKey?: string,
267→): Promise<Model<any>[]> {
268→	switch (type) {
