270→			return discoverOllamaModels(baseUrl, apiKey);
271→		case "llama.cpp":
272→			return discoverLlamaCppModels(baseUrl, apiKey);
273→		case "vllm":
274→			return discoverVLLMModels(baseUrl, apiKey);
275→		case "lmstudio":
276→			return discoverLMStudioModels(baseUrl, apiKey);
277→	}
278→}
