146→	private formatTokens(tokens: number): string {
147→		if (tokens >= 1000000) return `${(tokens / 1000000).toFixed(0)}M`;
148→		if (tokens >= 1000) return `${(tokens / 1000).toFixed(0)}`;
149→		return String(tokens);
