159→	/**
160→	 * Providers visible in the model selector.
161→	 * Only these cloud providers are shown; custom providers (Ollama, etc.) are always included.
162→	 */
163→	private static ALLOWED_PROVIDERS = new Set(["anthropic", "azure-openai-responses", "amazon-bedrock"]);
164→
165→	/**
166→	 * For providers with many models, only show models matching these prefixes.
167→	 * If a provider is not in this map, all its models are shown.
168→	 */
169→	private static PROVIDER_MODEL_FILTERS: Record<string, (id: string) => boolean> = {
170→		"amazon-bedrock": (id) => id.startsWith("anthropic.claude"),
171→	};
172→
173→	/**
174→	 * Bedrock cross-region inference profile prefix.
175→	 * EU/AP regions require model IDs prefixed with "eu." or "ap.".
176→	 * Set to empty string for US regions (bare model IDs work).
177→	 */
178→	private static BEDROCK_REGION_PREFIX = "eu.";
179→
180→	private getFilteredModels(): Array<{ provider: string; id: string; model: any }> {
181→		// Collect models from allowed known providers only
182→		const allModels: Array<{ provider: string; id: string; model: any }> = [];
183→		const knownProviders = getProviders();
184→
185→		for (const provider of knownProviders) {
186→			if (!ModelSelector.ALLOWED_PROVIDERS.has(provider)) continue;
187→			const modelFilter = ModelSelector.PROVIDER_MODEL_FILTERS[provider];
188→			const models = getModels(provider as any);
189→			for (const model of models) {
190→				if (modelFilter && !modelFilter(model.id)) continue;
191→				// Bedrock non-US regions need cross-region inference profile IDs
192→				if (provider === "amazon-bedrock" && ModelSelector.BEDROCK_REGION_PREFIX) {
193→					const prefixedId = ModelSelector.BEDROCK_REGION_PREFIX + model.id;
194→					allModels.push({ provider, id: prefixedId, model: { ...model, id: prefixedId } });
195→				} else {
196→					allModels.push({ provider, id: model.id, model });
197→				}
198→			}
199→		}
200→
201→		// Add custom provider models
202→		for (const model of this.customProviderModels) {
203→			allModels.push({ provider: model.provider, id: model.id, model });
204→		}
205→
206→		// Filter models based on search and capability filters
207→		let filteredModels = allModels;
208→
209→		// Apply search filter
210→		if (this.searchQuery) {
211→			filteredModels = filteredModels.filter(({ provider, id, model }) => {
212→				const searchTokens = this.searchQuery
213→					.toLowerCase()
214→					.split(/\s+/)
215→					.filter((t) => t);
216→				const searchText = `${provider} ${id} ${model.name}`.toLowerCase();
217→				return searchTokens.every((token) => searchText.includes(token));
218→			});
219→		}
220→
221→		// Apply capability filters
222→		if (this.filterThinking) {
223→			filteredModels = filteredModels.filter(({ model }) => model.reasoning);
224→		}
225→		if (this.filterVision) {
226→			filteredModels = filteredModels.filter(({ model }) => model.input.includes("image"));
227→		}
228→
229→		// Sort: current model first, then by provider
230→		filteredModels.sort((a, b) => {
231→			const aIsCurrent = modelsAreEqual(this.currentModel, a.model);
232→			const bIsCurrent = modelsAreEqual(this.currentModel, b.model);
233→			if (aIsCurrent && !bIsCurrent) return -1;
234→			if (!aIsCurrent && bIsCurrent) return 1;
235→			return a.provider.localeCompare(b.provider);
236→		});
237→
238→		return filteredModels;
239→	}
