242→		requestAnimationFrame(() => {
243→			const scrollContainer = this.scrollContainerRef.value;
244→			const selectedElement = scrollContainer?.querySelectorAll("[data-model-item]")[
245→				this.selectedIndex
246→			] as HTMLElement;
247→			if (selectedElement) {
248→				selectedElement.scrollIntoView({ block: "nearest", behavior: "smooth" });
249→			}
250→		});
251→	}
