 20→ * Fetch a session by ID and verify ownership.
 21→ * Sends 404 / 403 responses when appropriate and returns null.
 22→ */
 23→async function getOwnedSession(
 24→	req: Request,
 25→	res: Response,
 26→): Promise<SessionRow | null> {
 27→	const db = getDatabase();
 28→	const { id } = req.params;
 29→
 30→	const result = await db.query<SessionRow>(
 31→		"SELECT * FROM sessions WHERE id = $1",
 32→		[id],
 33→	);
 34→
 35→	if (result.rows.length === 0) {
 36→		res.status(404).json({ success: false, error: "Session not found" });
 37→		return null;
 38→	}
 39→
 40→	const session = result.rows[0];
 41→
 42→	if (!isOwner(req, session.user_id)) {
 43→		res.status(403).json({ success: false, error: "Forbidden" });
 44→		return null;
 45→	}
 46→
 47→	return session;
 48→}
