 56→	// ---------------------------------------------------------------------------
 57→	// SSE endpoint — uses ticket auth (before requireAuth middleware)
 58→	// ---------------------------------------------------------------------------
 59→
 60→	router.get("/events", requireAuthOrToken, (req, res) => {
 61→		const userId = req.user!.userId;
 62→
 63→		// Set SSE headers
 64→		res.setHeader("Content-Type", "text/event-stream");
 65→		res.setHeader("Cache-Control", "no-cache");
 66→		res.setHeader("Connection", "keep-alive");
 67→		res.setHeader("X-Accel-Buffering", "no"); // nginx
 68→		res.flushHeaders();
 69→
 70→		// Send initial snapshot of all session statuses for this user
 71→		const statuses = sessionStatusService.getStatusesForUser(userId);
 72→		const snapshot: Record<string, string> = {};
 73→		for (const [sessionId, status] of statuses) {
 74→			snapshot[sessionId] = status;
 75→		}
 76→		res.write(`event: snapshot\ndata: ${JSON.stringify(snapshot)}\n\n`);
 77→
 78→		// Subscribe to status changes
 79→		const unsubscribe = sessionStatusService.subscribe(userId, (event) => {
 80→			res.write(`event: session_status\ndata: ${JSON.stringify(event)}\n\n`);
 81→		});
 82→
 83→		// Keep-alive ping every 15s
 84→		const pingInterval = setInterval(() => {
 85→			res.write(`:ping\n\n`);
 86→		}, 15_000);
 87→
 88→		// Cleanup on disconnect
 89→		req.on("close", () => {
 90→			clearInterval(pingInterval);
 91→			unsubscribe();
 92→		});
 93→	});
 94→
 95→	// All remaining routes require standard auth
 96→	router.use(requireAuth);
