// If no model known yet, resolve the default from available providers.
// Try preferred defaults first, then fall back to configured providers.
if (!model) {
	const available = registry.getAvailable();
	if (available.length > 0) {
		let chosen = undefined;
		// Try preferred defaults (only from configured providers)
		for (const pref of PREFERRED_DEFAULT_MODELS) {
			chosen = available.find(
				(m) => m.provider === pref.provider && m.id === pref.id && this.configuredProviders.has(m.provider),
			);
			if (chosen) break;
		}
		// Fall back to first model from any configured provider
		if (!chosen) {
			chosen = available.find(
				(m) => this.configuredProviders.has(m.provider),
			) ?? available[0];
		}
		model = { id: chosen.id, provider: chosen.provider, name: chosen.name, reasoning: (chosen as any).reasoning };
	}
}

